// Generated by TyraX. Do not edit - regenerated on every build.
// Live Link (debug builds): applies editor edits to the running game with no
// rebuild. The editor writes livelink.bin next to the ELF; this script polls
// it over host:, patches transforms/colors in place, spawns newly added
// objects from equal-recipe templates and hides deleted ones.
#include <tyra>
#include <algorithm>
#include <cstdio>
#include <cstring>
#include "scripts/script.hpp"

namespace Iop_compute {
namespace {

typedef unsigned long long llu64;
constexpr u32 LL_MAGIC = 0x4C4C5854;  // "TXLL"
constexpr u32 LL_VERSION = 2;
constexpr int LL_HEADER = 24;
constexpr int LL_STRIDE = 64;  // one record (id + template + 12 floats)
// Largest authored object table across scenes - table bounds.
constexpr int LL_MAX_OBJECTS = 17;
// Live-spawned clones tracked at once; matches the game's
// MAX_SPAWNED_OBJECTS pool (spawnObject fails past it anyway).
constexpr int LL_MAX_SPAWNED = 32;

class LiveLink : public Script {
 public:
  void update(ScriptContext& ctx) override {
    // Scene (re)load resets runtime objects to their baked state: rebuild the
    // id lookup and re-apply the latest snapshot (lastSeq_ = 0).
    if (ctx.sceneGeneration != gen_) rebuildTables(ctx);

    // Over ps2link every fopen is a network round-trip - poll sparsely there;
    // PCSX2's Host Filesystem is plain local IO, poll ~10x/s.
    if (--cooldown_ > 0) return;
    cooldown_ = Tyra::IrxLoader::keepIopResident ? 25 : 6;

    static unsigned char buf[LL_HEADER +
                             (LL_MAX_OBJECTS + LL_MAX_SPAWNED) * LL_STRIDE + 4];
    FILE* f = fopen(Tyra::FileUtils::fromCwd("livelink.bin").c_str(), "rb");
    if (!f) return;  // no snapshot yet (or shipped without the editor)
    const size_t got = fread(buf, 1, sizeof(buf), f);
    fclose(f);
    if (got < LL_HEADER + 4) return;

    u32 magic, version, seq;
    s32 scene, count;
    memcpy(&magic, buf + 0, 4);
    memcpy(&version, buf + 4, 4);
    memcpy(&seq, buf + 8, 4);
    memcpy(&scene, buf + 12, 4);
    memcpy(&count, buf + 16, 4);
    if (magic != LL_MAGIC || version != LL_VERSION) return;
    if (seq == lastSeq_) return;  // already applied
    if (scene != ctx.scene || count < 0 ||
        count > LL_MAX_OBJECTS + LL_MAX_SPAWNED)
      return;
    // Exact size + footer echo of seq: a torn write fails both.
    if (got != (size_t)(LL_HEADER + count * LL_STRIDE + 4)) return;
    u32 foot;
    memcpy(&foot, buf + LL_HEADER + count * LL_STRIDE, 4);
    if (foot != (seq ^ 0x5A5A5A5AU)) return;

    bool present[LL_MAX_OBJECTS] = {};
    bool presentSpawn[LL_MAX_SPAWNED] = {};
    for (int i = 0; i < count; ++i) {
      const unsigned char* r = buf + LL_HEADER + i * LL_STRIDE;
      llu64 id;
      s32 tmpl;
      float v[12];
      memcpy(&id, r + 0, 8);
      memcpy(&tmpl, r + 8, 4);
      memcpy(v, r + 16, 48);

      const int idx = findAuthored(id);
      if (idx >= 0) {
        if (idx < LL_MAX_OBJECTS) present[idx] = true;
        if (idx >= ctx.objectCount) continue;
        RuntimeObject& o = ctx.objects[idx];
        bool changed = patch(o, v);
        if (hiddenByLL_[idx]) {  // deleted then undone: restore
          o.visible = prevVisible_[idx];
          hiddenByLL_[idx] = false;
          changed = true;
        }
        if (changed) o.dirty = true;
        continue;
      }

      const int s = findSpawned(id);
      if (s >= 0) {
        presentSpawn[s] = true;
        const int slot = spawnedSlot_[s];
        if (slot < ctx.objectCount && ctx.objects[slot].active) {
          RuntimeObject& o = ctx.objects[slot];
          if (patch(o, v)) o.dirty = true;
        }
        continue;
      }

      // Unknown id = an object added in the editor after the build: clone
      // the equal-recipe template the editor picked, then patch the clone.
      if (tmpl >= 0 && ctx.spawnObject && spawnedCount_ < LL_MAX_SPAWNED) {
        const int slot = ctx.spawnObject(tmpl, v[0], v[1], v[2], v[4]);
        if (slot >= 0) {
          spawnedId_[spawnedCount_] = id;
          spawnedSlot_[spawnedCount_] = slot;
          presentSpawn[spawnedCount_] = true;
          ++spawnedCount_;
          if (slot < ctx.objectCount) {
            RuntimeObject& o = ctx.objects[slot];
            patch(o, v);
            o.dirty = true;
          }
        }
      }
    }

    // Authored objects missing from the snapshot were deleted in the editor:
    // hide them (geometry stays baked until a rebuild; collision remains -
    // an approximation, exactly like the Hide Object flow node).
    const int authored =
        SCENE_OBJECT_COUNTS[ctx.scene] < LL_MAX_OBJECTS
            ? SCENE_OBJECT_COUNTS[ctx.scene]
            : LL_MAX_OBJECTS;
    for (int i = 0; i < authored && i < ctx.objectCount; ++i) {
      if (present[i] || hiddenByLL_[i]) continue;
      prevVisible_[i] = ctx.objects[i].visible;
      ctx.objects[i].visible = false;
      hiddenByLL_[i] = true;
    }
    // Live-spawned clones missing from the snapshot: despawn (frees the slot).
    for (int s = spawnedCount_ - 1; s >= 0; --s) {
      if (presentSpawn[s]) continue;
      if (ctx.despawnObject) ctx.despawnObject(spawnedSlot_[s]);
      --spawnedCount_;
      spawnedId_[s] = spawnedId_[spawnedCount_];
      spawnedSlot_[s] = spawnedSlot_[spawnedCount_];
      presentSpawn[s] = presentSpawn[spawnedCount_];
    }
    lastSeq_ = seq;
  }

 private:
  static bool apply3(float* dst, const float* src) {
    if (dst[0] == src[0] && dst[1] == src[1] && dst[2] == src[2])
      return false;
    dst[0] = src[0], dst[1] = src[1], dst[2] = src[2];
    return true;
  }
  // dirty only on a real change - it costs a geometry rebuild.
  static bool patch(RuntimeObject& o, const float* v) {
    bool changed = false;
    changed |= apply3(o.data.position, v + 0);
    changed |= apply3(o.data.rotation, v + 3);
    changed |= apply3(o.data.scale, v + 6);
    changed |= apply3(o.data.color, v + 9);
    return changed;
  }

  // Sorted (hash -> authored index) lookup over the baked id table.
  void rebuildTables(const ScriptContext& ctx) {
    gen_ = ctx.sceneGeneration;
    lastSeq_ = 0;  // re-apply the latest snapshot after a reload
    spawnedCount_ = 0;  // scene reload despawned every clone
    memset(hiddenByLL_, 0, sizeof(hiddenByLL_));
    n_ = SCENE_OBJECT_COUNTS[ctx.scene] < LL_MAX_OBJECTS
             ? SCENE_OBJECT_COUNTS[ctx.scene]
             : LL_MAX_OBJECTS;
    const llu64* ids = SCENE_OBJECT_ID_TABLES[ctx.scene];
    for (int i = 0; i < n_; ++i) order_[i] = (short)i;
    std::sort(order_, order_ + n_,
              [&](short a, short b) { return ids[a] < ids[b]; });
    for (int i = 0; i < n_; ++i) sorted_[i] = ids[order_[i]];
  }
  int findAuthored(llu64 id) const {
    int lo = 0, hi = n_;
    while (lo < hi) {
      const int mid = (lo + hi) / 2;
      if (sorted_[mid] < id) lo = mid + 1;
      else hi = mid;
    }
    return (lo < n_ && sorted_[lo] == id) ? order_[lo] : -1;
  }
  int findSpawned(llu64 id) const {
    for (int s = 0; s < spawnedCount_; ++s)
      if (spawnedId_[s] == id) return s;
    return -1;
  }

  int cooldown_ = 1;
  u32 lastSeq_ = 0;
  unsigned int gen_ = 0xFFFFFFFFU;  // forces the first rebuild
  int n_ = 0;
  llu64 sorted_[LL_MAX_OBJECTS];
  short order_[LL_MAX_OBJECTS];
  bool hiddenByLL_[LL_MAX_OBJECTS] = {};
  bool prevVisible_[LL_MAX_OBJECTS] = {};
  llu64 spawnedId_[LL_MAX_SPAWNED];
  int spawnedSlot_[LL_MAX_SPAWNED];
  int spawnedCount_ = 0;
};

LiveLink g_liveLink;
static const bool g_liveLinkRegistered = []() {
  getScripts().push_back(&g_liveLink);
  return true;
}();

}  // namespace
}  // namespace Iop_compute
